<?php require 'includes/bootstrap.php';$q=trim((string)($_GET['q']??''));$cat=trim((string)($_GET['category']??''));$items=array_values(array_filter(products(),function($p)use($q,$cat){if(($p['status']??'')!=='published')return false;if($cat!==''&&($p['category']??'')!==$cat)return false;return product_score($p,$q)>=($q===''?1:45);}));usort($items,fn($a,$b)=>product_score($b,$q)<=>product_score($a,$q));$pageTitle='المنتجات | أبشر';require 'includes/header.php';?><section class="catalog-head"><span class="eyebrow">الكتالوج</span><h1><?=$q?'نتائج البحث عن: '.e($q):'كل المعدات'?></h1><form class="smart-search"><input name="q" value="<?=e($q)?>" placeholder="ابحث بالاسم أو الموديل"><button>بحث</button></form></section><div class="filter-row"><a class="<?=$cat===''?'active':''?>" href="catalog.php">الكل</a><?php foreach(categories()as$c):?><a class="<?=$cat===$c['name']?'active':''?>" href="catalog.php?category=<?=urlencode($c['name'])?>"><?=e($c['name'])?></a><?php endforeach;?></div><section class="section"><div class="product-grid"><?php foreach($items as$p):?><a class="product-card" href="product.php?slug=<?=urlencode($p['slug'])?>"><div class="product-image"><span><?=e(u_first($p['brand']??'م'))?></span></div><div class="product-body"><small><?=e($p['brand']??'')?> • <?=e($p['model']??'')?></small><h3><?=e($p['name'])?></h3><p><?=e($p['short_description']??'')?></p><div class="card-foot"><b><?=!empty($p['price'])?money($p['price']):e($p['price_label']??'اتصل للسعر')?></b><span>التفاصيل ←</span></div></div></a><?php endforeach;?><?php if(!$items):?><div class="empty"><h3>لم نجد المنتج بهذا الاسم</h3><p>جرّب كتابة جزء من الموديل فقط.</p></div><?php endif;?></div></section><?php require 'includes/footer.php';?>